), eligibility AS MATERIALIZED (
 SELECT s.*,NOT EXISTS(SELECT 1 FROM unnest(required_relations) r(name) WHERE to_regclass(r.name) IS NULL)
 AND NOT EXISTS(SELECT 1 FROM unnest(required_functions) f(signature)
 LEFT JOIN comparison c ON c.signature=regexp_replace(f.signature,'^public\.','')
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure(f.signature)
 WHERE p.oid IS NULL OR p.provolatile NOT IN('s','i') OR p.proowner<>'postgres'::regrole
 OR c.expected_catalog_sha IS NULL OR c.actual_catalog_sha IS DISTINCT FROM c.expected_catalog_sha) eligible
 FROM specs s
), measured AS MATERIALIZED (
 SELECT s.*,CASE WHEN eligible THEN (xpath('/table/row/actual/text()',query_to_xml(read_query,true,false,'')))[1]::text ELSE NULL END actual
 FROM eligibility s
), output AS (
 SELECT 'direct_function'::text section,d.ordinal::bigint ordinal,'public.'||d.signature item,
 jsonb_build_object('exists',c.actual_present,'oid',c.oid,
 'expected_reference','FAILING_VERIFIER_BASELINE_ONLY','production_expected_pin_proven',false,
 'provenance_status',d.provenance_status,'expected_metadata',d.expected_metadata,'actual_metadata',c.metadata,
 'expected_source_hash',c.expected_source_sha,'actual_source_hash',c.metadata->>'source_sha',
 'expected_catalog_hash',c.expected_catalog_sha,'actual_catalog_hash',c.actual_catalog_sha,
 'actual_pg_get_functiondef_hash',c.functiondef_sha,'expected_pg_get_functiondef_hash',NULL::text,
 'expected_definition_hash_status','NOT_CAPTURED_IN_COMPACT_BASELINE; see historical receipts with explicitly different hash scheme',
 'security_mode',CASE WHEN c.actual_present THEN CASE WHEN (c.metadata->>'definer')::boolean THEN 'DEFINER' ELSE 'INVOKER' END ELSE NULL END,
 'mismatching_properties',coalesce((SELECT jsonb_agg(jsonb_build_object('property',x.key,'expected',x.value,'actual',c.metadata->x.key) ORDER BY x.key)
 FROM jsonb_each(d.expected_metadata) x WHERE x.value IS DISTINCT FROM c.metadata->x.key),'[]'::jsonb)) details
 FROM direct_expected d LEFT JOIN comparison c USING(signature)
 UNION ALL SELECT 'function_universe',3,'complete_function_universe_diagnostic',
 jsonb_build_object('expected_reference','FAILING_VERIFIER_BASELINE_NOT_PRODUCTION_AUTHORITY',
 'expected_function_count',(SELECT count(*) FROM expected_functions),'actual_function_count',(SELECT count(*) FROM actual_functions),
 'complete_function_universe_exact',NOT EXISTS(SELECT 1 FROM comparison WHERE NOT expected_present OR NOT actual_present OR expected_catalog_sha IS DISTINCT FROM actual_catalog_sha),
 'missing_functions',coalesce((SELECT jsonb_agg(signature ORDER BY signature) FROM comparison WHERE expected_present AND NOT actual_present),'[]'::jsonb),
 'unexpected_functions',coalesce((SELECT jsonb_agg(signature ORDER BY signature) FROM comparison WHERE actual_present AND NOT expected_present),'[]'::jsonb),
 'definition_mismatch_functions',coalesce((SELECT jsonb_agg(signature ORDER BY signature) FROM comparison WHERE expected_present AND actual_present AND NOT source_equal),'[]'::jsonb),
 'security_mismatch_functions',coalesce((SELECT jsonb_agg(signature ORDER BY signature) FROM comparison WHERE expected_present AND actual_present AND NOT metadata_equal),'[]'::jsonb),
 'definition_comparison','prosrc SHA256; original raw functiondef expected hashes unavailable',
 'security_comparison','all non-prosrc catalog properties including identity, return type, language, config and ACL')
 UNION ALL SELECT 'function_mismatches',4,'all_mismatch_details',
 coalesce((SELECT jsonb_agg(jsonb_build_object('signature',signature,'exists',actual_present,'expected_present',expected_present,
 'expected_source_hash',expected_source_sha,'actual_source_hash',metadata->>'source_sha',
 'source_equal',source_equal,'metadata_equal',metadata_equal,'expected_catalog_hash',expected_catalog_sha,
 'actual_catalog_hash',actual_catalog_sha,'actual_metadata',metadata,'actual_pg_get_functiondef_hash',functiondef_sha)
 ORDER BY signature) FROM comparison WHERE NOT expected_present OR NOT actual_present OR expected_catalog_sha IS DISTINCT FROM actual_catalog_sha),'[]'::jsonb)
 UNION ALL SELECT 'interpretation',5,'prior_cascade_not_runtime_failures',
 jsonb_build_object('direct_catalog_failures_reported',2,'aggregate_guard_failures',1,'suppressed_reads',17,
 'parity_was_executed_by_failed_gate',false,'pricing_data_drift_proven',false,
 'dependency_path','catalog differences -> catalog_guard=false -> eligibility=false -> 17 NULL results',
 'root_classification','AWAIT_PRODUCTION_METADATA_AND_PROVENANCE; never overwrite production to match a fixture')
 UNION ALL SELECT 'session',6,'read_only_execution',
 jsonb_build_object('transaction_read_only',current_setting('transaction_read_only'),'isolation',current_setting('transaction_isolation'),
 'statement_timeout',current_setting('statement_timeout'),'write_authorized',false,'expected_rows',74,'backup_verified_by_sql',false)
 UNION ALL SELECT section,6+ordinal,name,
 jsonb_build_object('expected',expected,'actual',actual,'eligible',eligible,
 'status',CASE WHEN NOT eligible THEN 'NOT_MEASURED_MISSING_RELATION_OR_OWN_HELPER_PIN' WHEN expected='REPORT_ONLY' THEN 'EVIDENCE_ONLY'
 WHEN actual IS NULL THEN 'NULL_RESULT' WHEN actual=expected THEN 'PASS' ELSE 'MISMATCH' END,'global_catalog_guard_used',false)
 FROM measured
) SELECT section,ordinal,item,details FROM output ORDER BY ordinal;
